//! Replays the golden corpus generated by
//! `electricity/scripts/generate_dotenv_corpus.py` -- python-dotenv's
//! own `dotenv_values` output for a synthetic `.env` text -- against
//! this crate's [`electricity_config::dotenv::dotenv_values`].
//!
//! The corpus is checked in (`tests/golden/dotenv_corpus.json`); CI
//! separately regenerates it with Python 3.11 and the pinned
//! `python-dotenv` version and fails the build if it differs
//! (`.github/workflows/electricity-generated.yml`), so this test only
//! needs to trust the committed file.

use electricity_config::dotenv::dotenv_values;
use electricity_value::{Dict, Value};
use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn load_corpus() -> Vec<Value> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/dotenv_corpus.json");
    let text = fs::read_to_string(&path).expect("golden/dotenv_corpus.json must exist");
    let value = electricity_json::loads(&text).expect("golden corpus must be valid JSON");
    match &value {
        Value::List(cases) => cases.clone(),
        other => panic!("expected a JSON array of cases, got {other:?}"),
    }
}

fn get<'a>(dict: &'a Dict, key: &str) -> Option<&'a Value> {
    dict.get(&Value::Str(key.to_string()))
}

fn s(dict: &Dict, key: &str) -> String {
    get(dict, key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("missing string field {key:?}"))
        .to_string()
}

fn string_map(value: Option<&Value>) -> HashMap<String, String> {
    let Some(Value::Dict(dict)) = value else {
        return HashMap::new();
    };
    dict.iter()
        .map(|(k, v)| (k.py_str(), v.as_str().unwrap_or_default().to_string()))
        .collect()
}

#[test]
fn every_case_in_the_corpus_matches_the_rust_dotenv_port() {
    let corpus = load_corpus();
    assert!(!corpus.is_empty(), "corpus must not be empty");

    for case in &corpus {
        let dict = case.as_dict().expect("each case must be an object");
        let name = s(dict, "name");
        let text = s(dict, "text");
        let real_env = string_map(get(dict, "real_env"));
        let expect = get(dict, "expect")
            .and_then(Value::as_dict)
            .unwrap_or_else(|| panic!("case {name}: missing expect"));

        let actual = dotenv_values(&text, &real_env);

        let expect_keys: Vec<String> = expect.keys().map(Value::py_str).collect();
        let actual_keys: Vec<String> = actual.keys().cloned().collect();
        assert_eq!(actual_keys, expect_keys, "case {name}: key set/order");

        for (key, expected_value) in expect.iter() {
            let key = key.py_str();
            let actual_value = actual
                .get(&key)
                .unwrap_or_else(|| panic!("case {name}: missing key {key:?} in actual output"));
            match expected_value {
                Value::None => assert_eq!(
                    *actual_value, None,
                    "case {name}: key {key:?} expected no value"
                ),
                Value::Str(expected) => assert_eq!(
                    actual_value.as_deref(),
                    Some(expected.as_str()),
                    "case {name}: key {key:?} value"
                ),
                other => panic!("case {name}: unexpected expect value shape {other:?}"),
            }
        }
    }
}
